{"code":"def compute(vars):
    cash_dividends_paid = vars["v1"]
    dividends_per_common_share = vars["v2"]

    if dividends_per_common_share == 0:
        return None

    shares_outstanding = cash_dividends_paid / dividends_per_common_share
    return {
        "value": shares_outstanding,
        "trace": {
            "cash_dividends_paid": cash_dividends_paid,
            "dividends_per_common_share": dividends_per_common_share,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }"}
